/*
 * prog49_bst – binary‑search‑tree utility
 *
 * Behaviour (as observed from the original binary):
 *
 *   prog49_bst MODE [NUM ...]
 *
 *   MODE  : "in"  – inorder traversal
 *           "pre" – preorder traversal
 *           "post"– postorder traversal
 *
 *   NUM   : signed decimal integers (parsed with strtol)
 *
 *   The program builds a BST from the supplied numbers (duplicates are
 *   inserted to the right subtree).  After the tree is built it prints
 *   the requested traversal.  Values are printed as decimal numbers,
 *   separated by a single space, followed by a newline.
 *
 *   If no numbers are supplied the tree is empty and the program prints
 *   "EMPTY" followed by a newline.
 *
 *   If the mode string is not one of the three supported values the
 *   program prints "INVALID_MODE" followed by a newline.
 *
 *   The original binary limited the tree to 64 nodes and ignored any
 *   additional arguments; this implementation follows the same limit.
 *
 *   The program returns 0 on all paths (the original binary also returns
 *   0).
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_NODES 64
#define NIL       -1

/* Global storage – exactly as the original binary used */
static long  value[MAX_NODES];
static int   left[MAX_NODES];
static int   right[MAX_NODES];
static int   root = NIL;
static int   used = 0;

/* Insert a value into the BST */
static void insert(long v)
{
    int *link = &root;          /* pointer to the child field we will follow */
    int  cur  = root;

    while (cur != NIL) {
        if (v < value[cur]) {
            link = &left[cur];
            cur  = left[cur];
        } else {
            link = &right[cur];
            cur  = right[cur];
        }
    }

    /* allocate a new node if we still have space */
    if (used >= MAX_NODES)
        return;                 /* original code silently ignored excess nodes */

    value[used] = v;
    left[used]  = NIL;
    right[used] = NIL;
    *link = used;               /* link the new node into the tree */
    ++used;
}

/* Traversal helpers – they all share the same printing logic */
static void print_value(long v, int *first)
{
    if (!*first)
        putchar(' ');
    printf("%ld", v);
    *first = 0;
}

static void inorder(int node, int *first)
{
    if (node == NIL) return;
    inorder(left[node],  first);
    print_value(value[node], first);
    inorder(right[node], first);
}

static void preorder(int node, int *first)
{
    if (node == NIL) return;
    print_value(value[node], first);
    preorder(left[node],  first);
    preorder(right[node], first);
}

static void postorder(int node, int *first)
{
    if (node == NIL) return;
    postorder(left[node],  first);
    postorder(right[node], first);
    print_value(value[node], first);
}

int main(int argc, char *argv[])
{
    const char *mode;
    int i;
    int first = 1;          /* flag used to avoid a leading space */

    if (argc < 2) {
        puts("INVALID_MODE");
        return 0;
    }
    mode = argv[1];
    if (strcmp(mode, "in") && strcmp(mode, "pre") && strcmp(mode, "post")) {
        puts("INVALID_MODE");
        return 0;
    }

    for (i = 2; i < argc && used < MAX_NODES; ++i) {
        char *endptr;
        long v = strtol(argv[i], &endptr, 10);
        (void)endptr;               /* original code ignored conversion errors */
        insert(v);
    }

    if (root == NIL) {
        puts("EMPTY");
    } else {
        if (!strcmp(mode, "in"))
            inorder(root, &first);
        else if (!strcmp(mode, "pre"))
            preorder(root, &first);
        else
            postorder(root, &first);
        putchar('\n');
    }

    return 0;
}
